{
  "command": "mkdir -p /tmp/zt/empty && cd /tmp/zt && node --test empty/ >/tmp/zt/out1.txt 2>&1; echo \"EMPTY_DIR_EXIT=$?\"; tail -3 /tmp/zt/out1.txt"
}

{
  "command": "cd /tmp/zt && printf 'const t=require(\"node:test\");const a=require(\"node:assert\");t.test(\"ok\",()=>a.equal(1,1));\\n' > empty/a.test.js && node --test empty/ >/tmp/zt/out2.txt 2>&1; echo \"WITH_TEST_EXIT=$?\"; grep -E \"^# (pass|fail)\" /tmp/zt/out2.txt; rm -f empty/a.test.js; mkdir -p /tmp/zt/empty/sub && node --test empty/ >/dev/null 2>&1; echo \"EMPTY_WITH_SUBDIR_EXIT=$?\""
}

{
  "command": "cat /tmp/zt/out2.txt; echo \"==== retry ====\"; cd /tmp/zt && printf 'const t=require(\"node:test\");const a=require(\"node:assert\");t.test(\"ok\",()=>a.equal(1,1));\\n' > empty/a.test.js && node --test empty/ >/tmp/zt/out3.txt 2>&1; echo \"EXIT=$?\"; cat /tmp/zt/out3.txt"
}

{
  "command": "cd /tmp/zt && ls empty && node --test empty >/tmp/zt/out4.txt 2>&1; echo \"NO_SLASH_EXIT=$?\"; tail -12 /tmp/zt/out4.txt"
}

{
  "command": "cd /tmp/zt && head -20 out4.txt; echo \"=== explicit file ===\"; node --test empty/a.test.js >/dev/null 2>&1; echo \"FILE_EXIT=$?\"; echo \"=== glob ===\"; node --test \"empty/**/*.test.js\" >/tmp/zt/out5.txt 2>&1; echo \"GLOB_EXIT=$?\"; tail -10 /tmp/zt/out5.txt"
}

{
  "command": "cd /tmp/zt && echo \"=== glob zero-match ===\"; rm -f empty/a.test.js; node --test \"empty/**/*.test.js\" >/tmp/zt/o6.txt 2>&1; echo \"GLOB_ZERO_EXIT=$?\"; tail -4 /tmp/zt/o6.txt; echo \"=== cwd discovery ===\"; cd empty && node --test >/tmp/zt/o7.txt 2>&1; echo \"CWD_ZERO_EXIT=$?\"; tail -4 /tmp/zt/o7.txt; cd /tmp/zt && printf 'const t=require(\"node:test\");t.test(\"ok\",()=>{});\\n' > empty/b.test.js && echo \"=== cwd discovery with file ===\" && cd empty && node --test >/tmp/zt/o8.txt 2>&1; echo \"CWD_ONE_EXIT=$?\"; tail -6 /tmp/zt/o8.txt"
}

{
  "command": "node --help | grep -i \"test\" | head -30; echo \"==== compound with test ====\"; cd /tmp/zt && printf 'const t=require(\"node:test\");t.test(\"ok\",()=>{});\\n' > empty/a.test.js && printf 'const t=require(\"node:test\");t.test(\"sub-ok\",()=>{});\\n' > empty/sub/c.test.js && find empty -name '*.test.js' -print -quit | grep -q . && node --test \"empty/**/*.test.js\" >/tmp/zt/o9.txt 2>&1; echo \"COMPOUND_WITH_TESTS_EXIT=$?\"; grep -E \"tests|pass|fail\" /tmp/zt/o9.txt | head -3"
}

{
  "command": "cd /tmp/zt && rm -f empty/a.test.js empty/sub/c.test.js && find empty -name '*.test.js' -print -quit | grep -q . && node --test \"empty/**/*.test.js\" >/dev/null 2>&1; echo \"COMPOUND_ZERO_EXIT=$?\"; find nonexistent -name '*.test.js' -print -quit | grep -q . && echo no; echo \"COMPOUND_NODIR_EXIT=$?\""
}

{
  "command": "cd /tmp/zt && ls empty/ && rm -f empty/*.test.js empty/sub/*.test.js && ls -R empty/ && find empty -name '*.test.js' -print -quit | grep -q . && node --test \"empty/**/*.test.js\" >/dev/null 2>&1; echo \"TRUE_ZERO_EXIT=$?\""
}

